import { useEffect } from "react";
export const useResize = (callback, active) => {
    useEffect(() => {
        if (!active) {
            return;
        }
        window.addEventListener("resize", callback);
        // eslint-disable-next-line consistent-return
        return () => {
            window.removeEventListener("resize", callback);
        };
    }, [callback, active]);
};
